	// NamespaceCreateDto
	NamespaceCreateDto_DefaultApplyApprovalThreshold    = "The number of Users (or Service Principals) that need to approve before an 'Apply' plan is executed. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself. If set neither on Module nor on Namespace then a threshold of 0 is used."
	NamespaceCreateDto_DefaultApprovalTimeoutMinutes    = "The number of minutes a Job should remain in the 'WaitingForApproval' in the case of an 'Apply' or 'Destroy' plan that requires approval. After this time elapses the Job will be stopped and any queued Jobs will start. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself. If set neither on Module nor on Namespace the Jobs will wait for an approval decision indefinitely."
	NamespaceCreateDto_DefaultCleanInitEnabled          = "Setting will remove all .terraform* files and folders (state files, locks, downloaded providers, downloaded modules etc.) and perform a clean init every time the Module is executed. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself."
	NamespaceCreateDto_DefaultDestroyApprovalThreshold  = "The number of Users (or Service Principals) that need to approve before an 'Destroy' plan is executed. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself. If set neither on Module nor on Namespace then a threshold of 0 is used."
	NamespaceCreateDto_DefaultDriftCheckEnabled         = "Setting this to true will periodically trigger an Apply job to check for drift in the deployed infrastructure. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself."
	NamespaceCreateDto_DefaultDriftCheckIntervalMinutes = "The number of minutes between drift checks. If not set, the system default (24 hours) is used. Note that irrespective of what is set here, these those will not be fired more regularly than the minimum internal as defined by your subscription tier. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself."
	NamespaceCreateDto_DefaultEngine                    = "Determines which binary will be used during deployment. Must be one of 'OpenTofu', 'Terraform' or 'Pulumi'. Setting this to 'OpenTofu' will use `tofu`. Setting it to 'Terraform' will use `terraform`. Setting this to 'Pulumi' will use `pulumi`. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself."
	NamespaceCreateDto_DefaultTriggerPathFilterEnabled  = "Defaults to 'false'. If 'true', Modules in this Namespace with `trigger_on_source_changed` only fire when a commit actually changes their watched directories instead of on every commit to the tracked source. All modules in this Namespace will use this value, unless explicitly overriden on the Module itself."
	NamespaceCreateDto_Name                             = "Name of the Namespace. Must be unique in combination with `stack_id`."
	NamespaceCreateDto_StackId                          = "ID of the Namespace's parent Stack."
	NamespaceCreateDto_TriggerBehaviourOnModified       = "Behaviour with respect to applying modules within the Namespace if any of the fields on the Namespace resource (or any of its Param, Env Var or Extra File resources) has changed. Must be one of 'TriggerAllImmediately' or 'DoNotTrigger'. Setting to 'TriggerAllImmediately' will trigger *all* Modules within the Stack to run an apply Job simultaneously. Setting to 'DoNotTrigger' will do nothing. The default (and recommended) setting is 'DoNotTrigger'."

